local KTool = CS.Engine.Lib.KTool

local ActionDarkDreamTeamHeadNode = Class('ActionDarkDreamTeamHeadNode')
function ActionDarkDreamTeamHeadNode:__init()
    self.questId = nil
    self.cardInfo = nil
    self.index = nil
end

function ActionDarkDreamTeamHeadNode:__delete()
    self.questId = nil
    self.cardInfo = nil
    self.index = nil
end

function ActionDarkDreamTeamHeadNode:Awake()
    SetButtonAction(self.BtnAddRole.gameObject,Bind(self,self.OnBtnHeadClick))
end

function ActionDarkDreamTeamHeadNode:RefreshTeamInfo(cardInfo, questId, index,groupId)
    self.questId = questId
    self.cardInfo = cardInfo
    self.index = index
    self.groupId = groupId
    if not isNull(cardInfo) and next(cardInfo) then
        KTool.SetActive(self.CommonSmallHeadNode.gameObject,true)
        local goEnv = CfUtils.GetLuaScr(self.CommonSmallHeadNode, "Game.Behaviours.CardHeadNode")
        local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        local cardDojo = cardComponent:GetCardById(cardInfo.refId)
        if cardDojo then
            goEnv:FreshNode(cardDojo, true)
            goEnv:FillFettersInfo(self.cardInfo)
            goEnv:SetCallBack(function()
                self:OnBtnHeadClick()
            end)
        end
    else
        KTool.SetActive(self.CommonSmallHeadNode.gameObject,false)
    end
end

function ActionDarkDreamTeamHeadNode:OnBtnHeadClick()
    ---@type ChaoticRecallUtils
    local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
    local dojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
    local data = dojo:GetUpBuffGroupDataByGroupId(self.groupId)
    local upGroup = dojo:GetUpGroupDataByGroupId(self.groupId)

    CS.Engine.UI.UIModule.OpenDialog(
            {id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self.questId, upBuffData = data , upGroup = upGroup, teamIndex = self.index },
            } , {
                { id = Constants.UITypeIds.ActionDarkDreamLevelDetails },
            })
end

function ActionDarkDreamTeamHeadNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActionDarkDreamTeamHeadNode